from pathlib import Pathimport json, os, timeimport numpy as npimport pandas as pdimport requestsROOT = Path(__file__).resolve().parent.parentRAW = ROOT / 'data' / 'raw'RAW.mkdir(parents=True, exist_ok=True)SAMPLE = RAW / 'multisat_2024_recent_sample.csv'HISTORY = RAW / 'multisat_2024_recent_gp_history.json'BASE = 'https://www.space-track.org/basicspacedata/query'BANDS = [(200,350),(350,500),(500,650),(650,800)]PER_BAND = 25RNG = np.random.default_rng(2024)def query(session, path):    r = session.get(BASE + path, timeout=180)    r.raise_for_status()    try:        data = r.json()    except ValueError as exc:        raise RuntimeError('Response was not JSON: check Space-Track login and rate limits') from exc    if not isinstance(data, list):        raise RuntimeError(f'Unexpected Space-Track response: {str(data)[:300]}')    return datadef login():    u, p = os.getenv('SPACETRACK_USERNAME'), os.getenv('SPACETRACK_PASSWORD')    if not u or not p:        raise RuntimeError('Set SPACETRACK_USERNAME and SPACETRACK_PASSWORD first')    s = requests.Session()    r = s.post('https://www.space-track.org/ajaxauth/login',               data={'identity':u,'password':p}, timeout=30)    r.raise_for_status()    try:        d = r.json()        if isinstance(d, dict) and str(d.get('Login','')).lower() == 'failed':            raise RuntimeError('Space-Track login rejected')    except ValueError:        pass    return sdef altitude(mm):    n = pd.to_numeric(mm, errors='coerce') * (2*np.pi/86400)    return (398600.4418/(n**2))**(1/3)-6371.def main():    with login() as s:        if not SAMPLE.exists():            snapshots = []            # Query non-overlapping catalog-number ranges instead of requesting            # only the first 10,000 low-numbered historical objects.            for low in range(40000, 61000, 1000):                high = low + 999                path = (f'/class/gp_history/EPOCH/2024-05-01--2024-05-02'                        f'/NORAD_CAT_ID/{low}--{high}/MEAN_MOTION/13--17'                        '/orderby/NORAD_CAT_ID%20asc,EPOCH%20asc/limit/10000/format/json')                records = query(s, path)                print(f'IDs {low}-{high}: {len(records)} orbital records')                if len(records) >= 10000:                    raise RuntimeError(f'Range {low}-{high} hit its cap; narrow the ID windows')                snapshots.extend(records)                time.sleep(3)            if not snapshots:                raise RuntimeError('No recent catalog-number candidates found')            frame = pd.DataFrame(snapshots)            frame['NORAD_CAT_ID'] = pd.to_numeric(frame['NORAD_CAT_ID'], errors='coerce')            frame['altitude_km'] = altitude(frame['MEAN_MOTION'])            frame = frame.dropna(subset=['NORAD_CAT_ID','altitude_km','EPOCH'])            frame = frame.sort_values('EPOCH').drop_duplicates('NORAD_CAT_ID', keep='last')            frame = frame[(frame.altitude_km >= 200) & (frame.altitude_km < 800)].copy()            print(f'Unique objects between 200 and 800 km: {len(frame)}')            # Select potential candidates first, verify object class and launch year            # through SATCAT before choosing the final sample.            satcat_rows=[]            ids = frame['NORAD_CAT_ID'].astype(int).astype(str).tolist()            for i in range(0, len(ids), 100):                satcat_rows.extend(query(s, '/class/satcat/NORAD_CAT_ID/'                    + ','.join(ids[i:i+100]) + '/format/json'))                time.sleep(3)            cat = pd.DataFrame(satcat_rows)            if cat.empty:                raise RuntimeError('SATCAT returned no rows')            cat['NORAD_CAT_ID'] = pd.to_numeric(cat['NORAD_CAT_ID'], errors='coerce')            cat['launch_year'] = pd.to_numeric(                cat['INTLDES'].astype('string').str.extract(r'^(\d{4})-')[0],                errors='coerce')            cat = cat[cat['OBJECT_TYPE'].astype(str).str.upper() == 'PAYLOAD']            cat = cat[cat['launch_year'].between(2015, 2024, inclusive='both')]            cat = cat.drop_duplicates('NORAD_CAT_ID')            frame = frame.merge(cat[['NORAD_CAT_ID','launch_year','SATNAME','INTLDES']],                                on='NORAD_CAT_ID', how='inner')            print(f'Confirmed payloads launched 2015-2024: {len(frame)}')            picked=[]            for lo, hi in BANDS:                group = frame[(frame.altitude_km >= lo)&(frame.altitude_km < hi)]                n = min(PER_BAND,len(group))                print(f'{lo}-{hi} km: {len(group)} candidates; selecting {n}')                if n:                    sample = group.iloc[RNG.choice(len(group),size=n,replace=False)].copy()                    sample['altitude_band'] = f'{lo}-{hi} km'                    picked.append(sample)            if not picked:                raise RuntimeError('No confirmed recent payloads in target bands')            output = pd.concat(picked, ignore_index=True)            output = output.rename(columns={'NORAD_CAT_ID':'norad_id','SATNAME':'satellite_name'})            output[['norad_id','satellite_name','launch_year','INTLDES','altitude_km',                    'altitude_band']].to_csv(SAMPLE,index=False)            print('Saved:', SAMPLE, 'satellites:',len(output))        else:            print('Using cached sample:', SAMPLE)            output = pd.read_csv(SAMPLE)        if HISTORY.exists():            print('Using cached histories:', HISTORY)            return        ids = sorted(output['norad_id'].astype(int).astype(str).tolist())        records=[]        for i in range(0,len(ids),20):            batch = ids[i:i+20]            print(f'Downloading histories {i+1}-{min(i+20,len(ids))}/{len(ids)}')            path = ('/class/gp_history/NORAD_CAT_ID/' + ','.join(batch)                    + '/EPOCH/2024-04-25--2024-05-22'                    + '/orderby/NORAD_CAT_ID%20asc,EPOCH%20asc/format/json')            records.extend(query(s,path))            time.sleep(4)        HISTORY.write_text(json.dumps(records,indent=2))        print('Saved:', HISTORY, 'records:',len(records))        print('Original dataset was not modified.')if __name__ == '__main__':    main()